import{_ as a,o as n,c as t,a6 as r}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Understand rankings and competitions","description":"","frontmatter":{"title":"Understand rankings and competitions","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","translationRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","order":30},"headers":[],"relativePath":"en/user/points/rankings.md","filePath":"en/user/points/rankings.md","lastUpdated":1794611623000}'),i={name:"en/user/points/rankings.md"};function o(s,e,d,l,c,p){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="understand-rankings-and-competitions" tabindex="-1">Understand rankings and competitions <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to &quot;Understand rankings and competitions {#understand-rankings-and-competitions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Choose the appropriate ranked view and recognize the limits of the developing rankings workspace. You need incoming activity for meaningful scores. Start with the ordinary <a href="./rules.html">Points</a> leaderboard or the top-viewer panels in <a href="./../live/feed.html">Live feed</a> when you only need to inspect current viewers.</p><h2 id="use-the-right-view" tabindex="-1">Use the right view <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to &quot;Use the right view {#use-the-right-view}&quot;">​</a></h2><ol><li>In <strong>Points</strong>, search for a viewer and sort by points, level or viewer identity. Refresh before comparing a manual adjustment with an award.</li><li>In <strong>Live feed</strong>, inspect the available ranked viewer panels. These can receive ranking-engine snapshots independently of the point balance table.</li><li>For an overlay, open <a href="./../overlays/">Overlays</a>, select the ranking kind and inspect its source options. A configured ranking source must exist before its output can appear.</li></ol><p>The dedicated <strong>Rankings &amp; competitions</strong> workspace is experimental. Its frontend route is <code>#/rankings</code>, but it is deliberately hidden from the main navigation and is not restored as the startup tab. A missing sidebar item does not mean the route or ranking engine has been removed.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configure an experimental ranking <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to &quot;Configure an experimental ranking {#configure-an-experimental-ranking}&quot;">​</a></h2><p>If your environment exposes that workspace, start with one creator, one room, grouping by user and a session window. Add one advertised metric, such as <code>tiktok.like</code> / <code>like.count</code>, with weight <code>1</code>. Set a modest result limit and create the definition. The form also supports rolling and daily windows, with explicit duration/event bounds or timezone offset.</p><p>Read the resulting snapshot before introducing additional sources. Pause and resume affect ranking collection; reset intentionally clears ranking state. Competition options and vote-related sources have their own grouping rules. Do not assume a points reset also resets a competition, or that every custom grouping works with every metric.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Ordinary leaderboards are available; the dedicated management page remains experimental. Scores come from the host, not from counting displayed feed rows. Real broadcast/OBS acceptance and every competition combination are not established by this guide.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>Check creator, room, source enablement, window and pause state when scores stay empty. Remove unsupported source/group combinations rather than inventing field names. Preserve important data through <a href="./../preferences/backups.html">backups</a> before resets, and include definition ID and diagnostic code in a report.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>The Points table requests 100 viewers and filters/sorts only those received rows. Refreshing or sorting by name does not search the entire database. Feed rankings show 10 rows per creator/room session: gift diamonds for Top and counts for Likes, with tracking bounded to 5,000 viewers. They do not measure saved points. Compare units and session boundaries before comparing totals.</p>',15)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
